import{_ as t,o as n,c as r,a8 as o}from"./chunks/framework.ALLMRHJF.js";const m=JSON.parse('{"title":"Security and credentials","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-chefs-embed/developer/security-and-credentials.md","filePath":"content/plugins/bcew-chefs-embed/developer/security-and-credentials.md"}'),a={name:"content/plugins/bcew-chefs-embed/developer/security-and-credentials.md"};function s(d,e,i,c,l,p){return n(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="security-and-credentials" tabindex="-1">Security and credentials <a class="header-anchor" href="#security-and-credentials" aria-label="Permalink to “Security and credentials”">​</a></h1><p>The settings page requires the <code>manage_options</code> capability. Form save, deletion, and confirmation actions use WordPress admin-post handlers with nonce validation.</p><p>Each saved form is one row in <code>{prefix}bcew_chefs_credentials</code>, with the Form ID, encrypted API key, form name, confirmation message, created time, and user ID. On upgrade, a form name and confirmation still stored in <code>{prefix}bcew_chefs_options</code> are copied onto the matching credentials row, and that table is removed. API keys are encrypted before they are stored by <code>src/CredentialsManager.php</code>. <code>src/Crypto.php</code> encrypts them with libsodium <code>sodium_crypto_secretbox()</code>. The encryption key is derived from the WordPress authentication salts, so encrypted values depend on the WordPress installation&#39;s salts.</p><p>Implementation safeguard: do not decide whether a Form ID is new by calling <code>get_by_form_id()</code>. It returns <code>null</code> for both a missing row and an undecryptable key, while <code>save()</code> can still update an existing row. Use <code>CredentialsManager::form_exists()</code> to check for the row without decrypting the stored key. A valid replacement key for an existing row must preserve the saved form name and confirmation and report an update, even when the old key cannot be decrypted.</p><p>During form rendering, the server decrypts the API key and uses it only for the CHEFS token exchange. Basic Authentication is server-to-server. The API key remains server-side and is not included in block attributes, rendered HTML, frontend source, or REST responses. The short-lived token is intentionally returned by <code>embed-config</code> and the frontend assigns it to the CHEFS viewer&#39;s <code>auth-token</code> attribute so the browser can load the form. The token is not stored in the block&#39;s persisted attributes.</p><p>Do not commit API keys, add them to source code, or expose them in client-side code. Use the CHEFS settings page for configured credentials and use non-production credentials for local testing.</p><p>When moving a database between environments, remember that different WordPress salts cannot decrypt the same stored API-key ciphertext. A database-only migration may require the credentials to be entered again.</p>',7)])])}const u=t(a,[["render",s]]);export{m as __pageData,u as default};
